/**
 * Abogados del Ranking Legal Ecuador — campaña de invitación a la aplicación.
 *
 * Origen: base de los abogados que aparecen en rankinglegal.ec. Llegaron 1.312
 * filas que se reducen a 737 direcciones distintas, porque decenas de abogados
 * de una misma firma comparten el buzón general (info@apolo.ec aparecía 59
 * veces). De esas 737 se quitan las 9 que ya estaban en el directorio anterior:
 * nadie puede entrar dos veces por dos listas distintas.
 *
 * EL `nivel` NO ES DECORATIVO, DECIDE A QUIÉN SE LE ESCRIBE
 * --------------------------------------------------------
 * Un rebote hace más daño que un correo ignorado: los proveedores leen una
 * tasa alta de rebotes como «este remitente no sabe a quién le escribe» y
 * castigan al dominio entero. Por eso la base viene separada y la campaña
 * manda por defecto sólo el nivel A.
 *
 *   A — la dirección estaba publicada en el perfil del abogado en la web de
 *       su propia firma. Es real y es personal. Riesgo de rebote: mínimo.
 *
 *   B — deducida a partir del patrón de la firma (nombre.apellido@, f+apellido@).
 *       Nadie la ha visto escrita: los patrones van del 78 % al 100 % de
 *       acierto, así que un porcentaje de éstas rebota con seguridad. No se
 *       mandan sin haberlas verificado antes.
 *
 *   C — buzón general de la firma (info@, recepcion@). No rebota, pero lo
 *       abre quien atiende el teléfono, no el abogado: es la dirección con
 *       más probabilidad de acabar marcada como spam y la que menos devuelve.
 *
 * `areas` viene del ranking y permite afinar después: el correo habla de un
 * repositorio de jurisprudencia tributaria, y a quien litiga en propiedad
 * intelectual le interesa menos que a quien lleva tributario.
 *
 * El `id` es estable y viaja en el enlace de la tienda como `d=<id>`. Si se
 * agregan direcciones, van al final con el siguiente id libre; esta lista no
 * se reordena ni se reenumera.
 */

export type AbogadoRanking = {
  id: number;
  correo: string;
  nombre: string;
  firma: string;
  /** A = verificada · B = deducida por patrón · C = buzón general. */
  nivel: 'A' | 'B' | 'C';
  areas?: string;
};

export const CAMPANA_RANKING = 'ranking-legal-2026-09';

